    def get_line(vertical, k):
        return [grid[r][k] for r in range(h)] if vertical else grid[k][:]

    def repeat_count(vertical):
        n = w if vertical else h
        count = 0
        for k in range(n):
            a = get_line(vertical, k)
            if any(a[i] != 0 and a[j] == a[i]
                   for i in range(len(a)) for j in range(i + 1, len(a))):
                count += 1
        return count

    vertical = repeat_count(True) > repeat_count(False)
    out = [row[:] for row in grid]
    nlines = w if vertical else h

    for k in range(nlines):
        a = get_line(vertical, k)
        pairs = [(j - i, i, a[i]) for i in range(len(a)) if a[i]
                 for j in range(i + 1, len(a)) if a[j] == a[i]]
        if not pairs:
            continue

        period = min(d for d, _, _ in pairs)
        pair_positions = []
        pair_colors = set()
        for d, i, color in pairs:
            if d == period:
                pair_positions.extend((i, i + d))
                pair_colors.add(color)

        start = min(i for d, i, _ in pairs if d == period)
        phase = start % period
        aligned = [i for i in range(len(a)) if i % period == phase]
        other = [(i, a[i]) for i in aligned if a[i] and a[i] not in pair_colors]

        if other:
            seed, color = max(other)
            lo = min(pair_positions + [seed])
            hi = max(pair_positions + [seed])
        else:
            color = next(iter(pair_colors))
            lo, hi = 0, len(a) - 1

        for i in aligned:
            if lo <= i <= hi:
                if vertical:
                    out[i][k] = color
                else:
                    out[k][i] = color

    return out
